import {evidenceVoiceSource} from './evidence-voice-content.mjs';
import {evidenceVoiceView,startEvidenceVoice,setEvidenceLesson,setEvidenceText,annotateEvidence,answerEvidence,supportEvidence,exposeEvidence,skipEvidence,setEvidenceReading,keepEvidence,setEvidenceAnnotationDraft} from './evidence-voice-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const labels={interpretation:'My first interpretation',comparison:'My comparison of the accounts',reconsideration:'What I would change or retain, and why',claim:'My claim (optional planning)',detail:'A precise detail or passage (optional planning)',reasoning:'Why the detail supports my claim (optional planning)',paragraph:'My own paragraph for the town editor',objection:'A fair objection in my own words',revision:'My revised paragraph for the town editor',change:'What I changed or kept, and why (optional)'};
let leaveGuard;
const audio=(text,label)=>`<span data-ev-audio>${hearButton(text,label,'en')}</span>`;
export const evidenceVoiceEntry=()=>'<aside class="ev-entry"><h2>Evidence & voice</h2><p>Read a complete story, reconsider its narrators, and keep an argument for another reader.</p><a class="secondary" href="#learn/english">Open English</a></aside>';
function chapter(c,full=false){return `<section class="ev-chapter"><h3>${esc(c.title)}</h3>${audio(c.paragraphs.map(p=>p.text).join('\n\n'),`Hear ${c.title}`)}${c.paragraphs.map(p=>`<div class="ev-passage" id="ev-${full?'whole':'stage'}-${esc(p.id)}"><p class="ev-anchor">${esc(p.id)}</p><p>${esc(p.text)}</p>${btn(`data-ev-anchor="${esc(p.id)}"`,'Choose this passage for a note')}</div>`).join('')}</section>`;}
function whole(source){return `<details class="ev-whole" data-ev-whole><summary>The complete story · all four chapters</summary><p>${esc(source.notice)}</p>${source.chapters.map(c=>chapter(c,true)).join('')}</details>`;}
function keptBody(k){if(!k)return '<p>Not kept yet.</p>';const fields=k.kind==='revision'?['objection','revision','change']:['claim','detail','reasoning','paragraph'];const written=fields.filter(field=>(k.drafts[field]??'')!=='');return written.length?fields.map(field=>`<section><h4>${esc(labels[field])}</h4><p class="ev-own">${k.drafts[field]===undefined||k.drafts[field]===''?'No words added in this field.':esc(k.drafts[field])}</p></section>`).join(''):'<p class="ev-own">Kept blank — no words added.</p>';}
function snapshots(w){return `<details class="ev-versions"><summary>Read my kept versions</summary>${[['firstDraft','First kept draft'],['firstRevision','First kept revision'],['kept','Latest kept reader-facing piece']].map(([k,label])=>`<section data-ev-version="${k}"><h3>${label}</h3>${keptBody(w[k])}</section>`).join('')}</details>`;}

function annotations(w){const d=w.annotationDraft??{anchor:'',kind:'inference',text:''},ps=w.source.chapters.flatMap(c=>c.paragraphs);return `<section class="ev-annotation"><h3>Annotate an exact passage</h3><p>Choose a paragraph, label your note, and keep your own words. Labels are your choices; notes are ungraded.</p><label>Passage<select data-ev-note-anchor><option value="">Choose a passage</option>${ps.map(p=>`<option value="${esc(p.id)}" ${d.anchor===p.id?'selected':''}>${esc(p.id)} · ${esc(p.text.slice(0,70))}…</option>`).join('')}</select></label><p class="ev-note-preview">${esc(ps.find(p=>p.id===d.anchor)?.text||'The chosen exact paragraph will appear here.')}</p><label>My note is a<select data-ev-note-kind>${[['literal','Literal detail'],['inference','My inference'],['question','My question']].map(([v,l])=>`<option value="${v}" ${d.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>My annotation<textarea data-ev-note-text rows="3">
${esc(d.text)}</textarea></label>${btn('data-ev-note-keep','Keep this annotation')}<details><summary>My kept annotations (${w.annotations.length})</summary>${w.annotations.map(a=>`<article class="ev-kept-note"><h4>${esc(a.anchor)} · ${esc(a.kind)}</h4><blockquote>${esc(a.passage)}</blockquote><p class="ev-own">${esc(a.text||'Kept blank — no words added.')}</p></article>`).join('')||'<p>No kept annotations yet.</p>'}</details></section>`;}
function questions(w,l){return w.source.questions.filter(q=>q.lesson===l.id).map(q=>{const last=w.responses.filter(r=>r.question.id===q.id).at(-1);return `<fieldset class="ev-question"><legend>${esc(q.prompt)}</legend><div class="ev-choices">${q.choices.map(c=>btn(`data-ev-answer="${esc(q.id)}:${esc(c.id)}" aria-pressed="${last?.choice===c.id}"`,c.label)).join('')}</div>${last?`<p class="ev-feedback" id="ev-feedback-${esc(q.id)}" tabindex="-1"><strong>Last structured check:</strong> ${esc(last.feedback)}</p>`:''}</fieldset>`;}).join('');}
function lesson(w,l){const support=w.support[l.id]??[];return `<h2 id="ev-heading" tabindex="-1">${esc(l.title)}</h2><p>${esc(l.prompt)}</p><aside class="ev-support"><h3>Choose any help</h3><div class="ev-actions">${[['learn','Learn'],['guided','Guided walkthrough'],['hint','Hint'],['example','Different example'],['together','We’re working together']].map(([k,t])=>btn(`data-ev-support="${k}" aria-pressed="${support.includes(k)}"`,t)).join('')}</div>${['learn','guided','hint','example'].filter(k=>support.includes(k)).map(k=>`<section><h4>${{learn:'Learn',guided:'Guided walkthrough',hint:'Hint',example:'Different example'}[k]}</h4><p>${esc(l[k])}</p>${audio(l[k],`Hear ${k==='guided'?'the walkthrough':k==='example'?'the different example':k}`)}</section>`).join('')}${support.includes('together')?'<p>Working together is recorded separately from the structured responses.</p>':''}</aside>${l.id==='revise'?`<aside class="ev-earlier"><h3>Your first kept draft</h3>${w.firstDraft?keptBody(w.firstDraft):'<p>No first draft has been kept. You can write a revision directly, or visit Write for a reader.</p>'}</aside>`:''}<div class="ev-reading">${w.source.chapters.filter(c=>l.chapters.includes(c.id)).map(c=>chapter(c)).join('')}</div>${l.id==='later'?`<aside class="ev-revisit"><h3>Return to the earlier interpretation</h3>${['c1-p3','c3-p1','c3-p2'].map(id=>{const p=w.source.chapters.flatMap(c=>c.paragraphs).find(p=>p.id===id);return p?`<p><strong>${esc(id)}</strong> ${esc(p.text)}</p>`:'';}).join('')}<h4>Your first interpretation</h4><p class="ev-own">${esc(w.drafts.interpretation||'No earlier words were added. You can reconsider the narrated suspicion itself.')}</p></aside>`:''}${questions(w,l)}${annotations(w)}<section class="ev-writing"><h3>Your words for a reader</h3><p>These fields are ungraded. You can write, dictate to someone beside you, or discuss aloud. No text is sent anywhere. Each field holds up to 8,000 characters.</p>${l.fields.map(k=>`<label>${esc(labels[k]||k)}<textarea rows="${['paragraph','revision'].includes(k)?7:3}" data-ev-field="${esc(k)}">
${esc(w.drafts[k]??'')}</textarea></label>`).join('')}${['write','revise'].includes(l.id)?btn(`data-ev-keep="${l.id==='write'?'draft':'revision'}"`,l.id==='write'?'Keep my first draft / latest draft':'Keep my revision for the reader',true):''}${l.id==='revise'?'<p>Human review: What claim did the reader understand? Which detail supported it? Did the objection help you clarify or narrow it?</p>':''}${snapshots(w)}</section><details><summary>Reading report · kept until changed</summary><p>This report applies to later checks until you change it. A report is separate from an assessment of independent reading.</p><div class="ev-actions">${[['unobserved','Reading not observed'],['together','Read together'],['reported-independent','Reported read independently']].map(([v,t])=>btn(`data-ev-reading="${v}" aria-pressed="${w.reading===v}"`,t)).join('')}</div></details><div class="ev-actions">${btn('data-ev-skip',w.skipped.includes(l.id)?'This lesson is marked skipped':'Skip this lesson for now')}<a class="secondary" href="#learn/english">English sequence</a></div>`;}
export function evidenceVoicePage(state,requestedLesson){const v=evidenceVoiceView(state),w=v.work,source=w?.source??evidenceVoiceSource,requested=source.lessons.find(l=>l.id===requestedLesson),preview=requested&&(!w||w.lesson!==requested.id);const units=v.units.filter(u=>u.readable);const copyId=(()=>{let n=1,id='clock-river';while(Object.hasOwn(state.evidenceVoice?.units??{},id))id=`clock-river-copy-${n++}`;return id;})();const startKey=w?state.evidenceVoice.current:(!Object.hasOwn(state.evidenceVoice?.units??{},'clock-river')?'clock-river':copyId);return `<div class="ev-page" data-ev-root lang="en"><header><a class="back" href="#pathways">Subjects</a><p>English · a first sustained reading and writing sequence</p><h1>Evidence & voice</h1><p>${esc(source.title)} — a complete original story in four chapters. Choose any lesson; help is always available.</p></header>${v.status==='unavailable'?'<h2 id="ev-heading" tabindex="-1">Your earlier English record is retained</h2><p>This version cannot edit that format. It remains in notes downloads. Other subjects stay open.</p><a class="secondary" href="#notes">Open notes</a>':`<nav class="ev-lessons" aria-label="English lessons">${source.lessons.map((l,i)=>btn(`data-ev-open="${esc(l.id)}" data-ev-unit="${esc(startKey)}" aria-current="${w?.lesson===l.id&&!preview?'step':'false'}"`,`${i+1}. ${l.title}`)).join('')}</nav>${units.length>1||(!w&&units.length>0)?`<details class="ev-copies"><summary>Saved story copies</summary>${units.map(u=>btn(`data-ev-unit-open="${esc(u.id)}" aria-pressed="${!!w&&state.evidenceVoice.current===u.id}"`,`${u.title} · ${u.id}${w&&state.evidenceVoice.current===u.id?' · current':''}`)).join('')}</details>`:''}${v.units.some(u=>!u.readable)?'<p>An earlier unreadable story record is retained. A new copy can be opened without replacing it.</p>':''}${preview?`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">${esc(requested.title)}</h2><p>${esc(requested.prompt)}</p><p>${esc(requested.learn)}</p>${btn(`data-ev-open="${esc(requested.id)}" data-ev-unit="${esc(startKey)}"`,'Start / continue this lesson',true)}</section>`:w?lesson(w,source.lessons.find(l=>l.id===w.lesson)):`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">A clock falls silent. Whose account should you trust?</h2><p>Follow five connected lessons: read, compare, reconsider, write, revise. Start with reading or choose the writing task directly. Nothing is locked.</p>${btn(`data-ev-open="before" data-ev-unit="${esc(startKey)}"`,'Begin with the first account',true)}</section>`}${whole(source)}`}<p id="ev-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a class="secondary" href="#notes">Grown-up notes</a><a class="secondary" href="#pathways">Other subjects</a></footer></div>`;}
export function evidenceVoiceNotes(state){if(!Object.hasOwn(state,'evidenceVoice'))return '';const v=evidenceVoiceView(state);return `<details class="panel ev-notes"><summary>English · Evidence & voice</summary><p>A first sequence using a complete original story. Own writing and annotation notes are human-read and ungraded. Structured checks, support before each attempt, skips, shown text and reading reports remain separate. Visits and kept drafts do not establish course completion or independent reading.</p>${v.units.filter(u=>u.readable).map(u=>{const w=state.evidenceVoice.units[u.id];return `<h3>${esc(u.title)}</h3><p>${w.responses.length} structured attempts; ${w.annotations.length} kept annotations.</p>${snapshots(w)}`;}).join('')}<details><summary>Exact saved material and work (including retained formats)</summary><pre>${esc(JSON.stringify(state.evidenceVoice,null,2))}</pre></details></details>`;}
export function bindEvidenceVoice(state,{save,render,focus,canExport,explorerId,isActive,entryLesson}={}){
 leaveGuard?.abort();leaveGuard=new AbortController();const root=document.querySelector('[data-ev-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport},dirty=new Set();
 const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;
 const say=(text,take=false)=>{const n=root.querySelector('#ev-status');if(n){n.textContent=text;if(take)n.focus();}};
 const redraw=(message='',target='#ev-heading')=>{stopSpeech();save?.();render?.();const n=document.querySelector('#ev-status');if(n)n.textContent=message;focus?.(target);};
 const act=(el,fn,message='',target='#ev-heading')=>{if(!live(el))return false;if(dirty.size){say('Your visible words have not been saved. Shorten the indicated field or download earlier notes before leaving this page.',true);return false;}const r=fn();if(!r?.ok){say(r?.error||'This change could not be kept.',true);return false;}redraw(message||r.attempt?.feedback||'',target);return true;};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 on('[data-ev-open]',b=>act(b,()=>{const r=startEvidenceVoice(state,b.dataset.evUnit,{...o,lesson:b.dataset.evOpen});if(r.ok&&location.hash.startsWith('#learn/english/'))history.replaceState(null,'',`#learn/english/${b.dataset.evOpen}`);return r;},'Lesson opened. Choose any help.'));
 on('[data-ev-unit-open]',b=>act(b,()=>{if(!b.dataset.evUnitOpen)return {ok:false,error:'Choose a saved story copy.'};const r=startEvidenceVoice(state,b.dataset.evUnitOpen,o);if(r.ok&&location.hash.startsWith('#learn/english/'))history.replaceState(null,'',`#learn/english/${evidenceVoiceView(state).work.lesson}`);return r;},'Saved story copy opened.'));
 on('[data-ev-support]',b=>act(b,()=>supportEvidence(state,b.dataset.evSupport,o),'Support recorded for this lesson.',`[data-ev-support="${b.dataset.evSupport}"]`));
 on('[data-ev-reading]',b=>act(b,()=>setEvidenceReading(state,b.dataset.evReading,o),'Reading report kept.',`[data-ev-reading="${b.dataset.evReading}"]`));
 on('[data-ev-answer]',b=>{const [q,c]=b.dataset.evAnswer.split(':');act(b,()=>answerEvidence(state,q,c,o),'',`#ev-feedback-${q}`);});
 on('[data-ev-skip]',b=>act(b,()=>skipEvidence(state,o),'Marked skipped. Every lesson is still open.','[data-ev-skip]'));
 on('[data-ev-keep]',b=>act(b,()=>keepEvidence(state,b.dataset.evKeep,o),'Version kept. Your first kept draft and first revision stay available.',`[data-ev-keep="${b.dataset.evKeep}"]`));
 root.querySelectorAll('[data-ev-field]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;const r=setEvidenceText(state,el.dataset.evField,el.value,o);if(r.ok){dirty.delete(el.dataset.evField);el.removeAttribute('aria-invalid');save?.();say('Words saved on this device.');}else{dirty.add(el.dataset.evField);el.setAttribute('aria-invalid','true');say(r.error);}}));
 const noteDraft=()=>({anchor:root.querySelector('[data-ev-note-anchor]')?.value??'',kind:root.querySelector('[data-ev-note-kind]')?.value??'inference',text:root.querySelector('[data-ev-note-text]')?.value??''});
 const saveNote=el=>{if(!live(el))return false;const previous=evidenceVoiceView(state).work?.annotationDraft??{anchor:'',kind:'inference',text:''},draft={...previous};if(el.hasAttribute('data-ev-note-text'))draft.text=el.value;if(el.hasAttribute('data-ev-note-anchor'))draft.anchor=el.value;if(el.hasAttribute('data-ev-note-kind'))draft.kind=el.value;const r=setEvidenceAnnotationDraft(state,draft,o);if(r.ok){if(el.hasAttribute('data-ev-note-text'))dirty.delete('annotation');el.removeAttribute('aria-invalid');save?.();const w=evidenceVoiceView(state).work,p=w?.source.chapters.flatMap(c=>c.paragraphs).find(p=>p.id===draft.anchor);const preview=root.querySelector('.ev-note-preview');if(preview)preview.textContent=p?.text||'The chosen exact paragraph will appear here.';}else{if(el.hasAttribute('data-ev-note-text'))dirty.add('annotation');el.setAttribute('aria-invalid','true');say(r.error);}return r.ok;};
 root.querySelectorAll('[data-ev-note-anchor],[data-ev-note-kind],[data-ev-note-text]').forEach(el=>el.addEventListener(el.tagName==='TEXTAREA'?'input':'change',()=>saveNote(el)));
 on('[data-ev-anchor]',b=>{const select=root.querySelector('[data-ev-note-anchor]');if(!select){say('Open this lesson to keep a note on a passage.',true);return;}select.value=b.dataset.evAnchor;if(saveNote(select))select.focus();});
 on('[data-ev-note-keep]',b=>{const d=evidenceVoiceView(state).work?.annotationDraft??noteDraft();act(b,()=>annotateEvidence(state,d.anchor,d.kind,d.text,o),'Exact passage and annotation kept.','[data-ev-note-keep]');});
 root.querySelector('[data-ev-whole]')?.addEventListener('toggle',e=>{if(!e.target.open||!live(e.target)||!evidenceVoiceView(state).work)return;const ids=evidenceVoiceView(state).work.source.chapters.map(c=>c.id),r=exposeEvidence(state,ids,o);if(r.ok)save?.();else say(r.error);});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-ev-audio] [data-speak]');if(!b)return;if(!live(b)){e.stopImmediatePropagation();return;}if(!evidenceVoiceView(state).work)return;const r=supportEvidence(state,'audio',o);if(r.ok)save?.();else{e.stopImmediatePropagation();say(r.error);}},true);
 document.addEventListener('click',e=>{if(!dirty.size||!root.isConnected||root.contains(e.target))return;const control=e.target.closest('button,a,input,select,summary');if(control){e.preventDefault();e.stopImmediatePropagation();say('Your visible words have not been saved. Shorten the indicated field before changing explorer or leaving this page.',true);}},{capture:true,signal:leaveGuard.signal});
 root.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{if(dirty.size){e.preventDefault();say('Your visible words have not been saved. Shorten the indicated field before leaving this page.',true);}}));
}
